-- Preserve redirects from pre-V2 project URLs without restoring alias tables.
-- Stable DripJobs identifiers resolve the UUID targets at migration time.

create temporary table legacy_job_url_map (
  old_project_id text primary key,
  dripjobs_proposal_id text not null
) on commit drop;


do $$
begin
  if exists (
    select 1
    from legacy_job_url_map legacy
    left join public.quotes quote
      on quote.dripjobs_proposal_id = legacy.dripjobs_proposal_id
    left join public.jobs job
      on job.accepted_quote_id = quote.id
    where job.id is null
  ) then
    raise exception 'A legacy job URL does not resolve to one V2 job';
  end if;
end
$$;

with grouped as (
  select
    job.id as job_id,
    jsonb_agg(legacy.old_project_id order by legacy.old_project_id) as legacy_project_ids
  from legacy_job_url_map legacy
  join public.quotes quote
    on quote.dripjobs_proposal_id = legacy.dripjobs_proposal_id
  join public.jobs job
    on job.accepted_quote_id = quote.id
  group by job.id
)
update public.jobs job
set metadata = jsonb_set(
  coalesce(job.metadata, '{}'::jsonb),
  '{legacy_project_ids}',
  grouped.legacy_project_ids,
  true
)
from grouped
where grouped.job_id = job.id;

create temporary table legacy_lead_url_map (
  old_project_id text primary key,
  dripjobs_deal_id text not null
) on commit drop;


do $$
begin
  if exists (
    select 1
    from legacy_lead_url_map legacy
    left join public.leads lead
      on lead.dripjobs_deal_id = legacy.dripjobs_deal_id
    where lead.id is null
  ) then
    raise exception 'A legacy lead URL does not resolve to one V2 lead';
  end if;
end
$$;

with grouped as (
  select
    lead.id as lead_id,
    jsonb_agg(legacy.old_project_id order by legacy.old_project_id) as legacy_project_ids
  from legacy_lead_url_map legacy
  join public.leads lead
    on lead.dripjobs_deal_id = legacy.dripjobs_deal_id
  group by lead.id
)
update public.leads lead
set metadata = jsonb_set(
  coalesce(lead.metadata, '{}'::jsonb),
  '{legacy_project_ids}',
  grouped.legacy_project_ids,
  true
)
from grouped
where grouped.lead_id = lead.id;


